import{_ as o,o as n,c as i,ah as s,j as t}from"./chunks/framework.CzXlmEQi.js";const r="/projects/WirelessGlove/en/latest/assets/image1.7RINB_oj.webp",l="/projects/WirelessGlove/en/latest/assets/image1.w0AGb8Ve.webp",a="/projects/WirelessGlove/en/latest/assets/image1.DXbTiFeD.webp",d="/projects/WirelessGlove/en/latest/assets/image2.DJsZnCzd.webp",c="/projects/WirelessGlove/en/latest/assets/image1.CwfkAqI0.webp",h="/projects/WirelessGlove/en/latest/assets/image2.CxAOD4Ky.webp",g="/projects/WirelessGlove/en/latest/assets/image3.DBzKzY2N.webp",p="/projects/WirelessGlove/en/latest/assets/image4.x8yLVARu.webp",m="/projects/WirelessGlove/en/latest/assets/image5.DSh7sK6D.webp",y="/projects/WirelessGlove/en/latest/assets/image1.DxvDUtot.webp",u="/projects/WirelessGlove/en/latest/assets/image1.DTnplfBo.webp",w="/projects/WirelessGlove/en/latest/assets/image2.BpBdJRg1.webp",x="/projects/WirelessGlove/en/latest/assets/image3.XtLz_WbY.webp",_="/projects/WirelessGlove/en/latest/assets/image4.jGvzBYMd.webp",f="/projects/WirelessGlove/en/latest/assets/image5.Baze9ucg.webp",b="/projects/WirelessGlove/en/latest/assets/image6.BsKcIfmj.webp",v="/projects/WirelessGlove/en/latest/assets/image7.CQFa79Gs.webp",k="/projects/WirelessGlove/en/latest/assets/image8.gAd-GPR4.webp",j="/projects/WirelessGlove/en/latest/assets/image9.DHYRDDx6.webp",D="/projects/WirelessGlove/en/latest/assets/image10.O-ueJtc7.webp",G="/projects/WirelessGlove/en/latest/assets/image11.CbXPiEZt.webp",W="/projects/WirelessGlove/en/latest/assets/image12.D_T4198d.webp",S="/projects/WirelessGlove/en/latest/assets/image3.BBtn00tz.webp",T="/projects/WirelessGlove/en/latest/assets/image4.CrPv4YdH.webp",z="/projects/WirelessGlove/en/latest/assets/image5.DlG2usEX.webp",P="/projects/WirelessGlove/en/latest/assets/image6.CZE5PA09.webp",B="/projects/WirelessGlove/en/latest/assets/image7.lmhEjQMm.webp",A="/projects/WirelessGlove/en/latest/assets/image8.DOWVM5lZ.webp",F=JSON.parse('{"title":"1. Wireless Glove Introduction and Wearing","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.Wireless_Glove_Introduction_and_Wearing.md","filePath":"docs/1.Wireless_Glove_Introduction_and_Wearing.md"}'),C={name:"docs/1.Wireless_Glove_Introduction_and_Wearing.md"};function I(M,e,R,q,E,H){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="_1-wireless-glove-introduction-and-wearing" tabindex="-1">1. Wireless Glove Introduction and Wearing <a class="header-anchor" href="#_1-wireless-glove-introduction-and-wearing" aria-label="Permalink to &quot;1. Wireless Glove Introduction and Wearing&quot;">​</a></h1><p>The wireless glove consists of five potentiometers and uses a Bluetooth module to communicate w<span class="mark">ith devices</span>.</p><h2 id="_1-1-structure-introduction" tabindex="-1">1.1 Structure Introduction <a class="header-anchor" href="#_1-1-structure-introduction" aria-label="Permalink to &quot;1.1 Structure Introduction&quot;">​</a></h2><img loading="lazy" height="671" width="1269" src="'+r+'" style="width:800px;" class="common_img"><ol><li><p><strong>Potentiometers</strong>: There are five potentiometers <span class="mark">on the back of t</span>he wireless glove, which <span class="mark">are key components that</span> control the opening and closing of the uHand UNO.</p></li><li><p><strong>Gyroscope Acceleration Sensor (MPU6050)</strong>: It can obtain the acceleration and tile angle of the wireless glove in the x,y, and z axes. You can control the uHand UNO by rotating the wireless glove for more operations.</p></li><li><p><strong>Bluetooth Module</strong>: It is mainly used for communication between the wireless glove and the uHand UNO.</p></li><li><p><strong>Function Keys</strong>: The functions of these two keys are as follows:</p></li></ol><p>(1) <strong>DEL</strong>: Clear the history of Bluetooth connections.</p><p>(2) <strong>K3</strong>: Switch the control mode of the wireless glove.</p><p>(3) <strong>Reset Key</strong>: Restart the wireless glove.</p><p>(4) <strong>LED Indicators</strong>: Display the control mode of the wireless glove.</p><p>(5) <strong>USB Port</strong>: Used to connect to a PC for debugging and downloading programs.</p><p>(6) <strong>Power Port</strong>: Connect to a lithium battery to power the wireless glove, with a standard voltage of 7.4V.</p><h2 id="_1-2-wearing-method" tabindex="-1">1.2 Wearing Method <a class="header-anchor" href="#_1-2-wearing-method" aria-label="Permalink to &quot;1.2 Wearing Method&quot;">​</a></h2><img loading="lazy" height="1055" width="1268" src="'+l+'" style="width:800px;" class="common_img"><p>Open all straps. First, tie the finger straps at the last knuckles of each finger, and then tie the hand strap and wrist strap at the hand and wrist respectively. The final wearing effect is as follows (please refer to the video in the same path as this document for details):</p><img loading="lazy" height="732" width="976" src="'+a+'" style="width:500px;" class="common_img"><p style="text-align:center;">Front</p><img loading="lazy" height="736" width="585" src="'+d+'" style="width:500px;" class="common_img"><p style="text-align:center;">Back</p><h2 id="_1-3-device-pairing" tabindex="-1">1.3 Device Pairing <a class="header-anchor" href="#_1-3-device-pairing" aria-label="Permalink to &quot;1.3 Device Pairing&quot;">​</a></h2><ol><li><p><span class="mark">First, switch on the controlled device and ensure it is connected to the Bluetooth module.</span></p></li><li><p>Wear the wireless glove on the right hand, and make a fist with the palm facing down. Then power on the wireless glove and its LED indicators will light up.</p></li></ol><img loading="lazy" height="733" width="550" src="'+c+'" style="width:500px;" class="common_img"><img loading="lazy" height="733" width="550" src="'+h+'" style="width:500px;" class="common_img"><ol start="3"><li>After the LED indicators go off, stretch your hand. When the LEDs complete the second flashing, it means that the initialization of the wireless glove is completed. <span class="mark">(This process must be done every time you restart the glove.)</span></li></ol><img loading="lazy" height="733" width="550" src="'+g+'" style="width:500px;" class="common_img"><img loading="lazy" height="733" width="550" src="'+p+'" style="width:500px;" class="common_img"><ol start="4"><li><p>Press the <strong>‘DEL’</strong> key to clear the history of the Bluetooth connections.</p></li><li><p>After the clear is completed, the <strong>‘STA’</strong> indicator starts to flash, and the wireless glove will automatically connect to the device. When the connection is successful, the &quot;<strong>STA</strong>&quot; indicator <span class="mark">stays on.</span></p></li></ol><img loading="lazy" height="733" width="550" src="'+m+'" style="width:500px;" class="common_img"><h2 id="_1-4-control-modes-switching" tabindex="-1">1.4 Control Modes Switching <a class="header-anchor" href="#_1-4-control-modes-switching" aria-label="Permalink to &quot;1.4 Control Modes Switching&quot;">​</a></h2><p>You can press the <strong>‘K3’</strong> key on the wireless glove to switch control modes. The LEDs (D1 to D5) will provide feedback <span class="mark">on the currently selected mode.</span></p><img loading="lazy" height="370" width="659" src="'+y+'" style="width:500px;" class="common_img"><p>The corresponding relationship between the LED status and the mode is shown in the following table:</p><table tabindex="0"><thead><tr><th style="text-align:center;">LED status(D1-D5)</th><th style="text-align:center;">Mode</th></tr></thead><tbody><tr><td style="text-align:center;">All off</td><td style="text-align:center;">Biorobot Control Mode</td></tr><tr><td style="text-align:center;">1 on (D1)</td><td style="text-align:center;">Robotic Hand Control Mode (Right Hand)</td></tr><tr><td style="text-align:center;">2 on (D1, D2)</td><td style="text-align:center;"><span class="mark">Tank</span> Control Mode</td></tr><tr><td style="text-align:center;">3 on (D1, D2, D3)</td><td style="text-align:center;">Robotic Arm Control Mode (PWM Servo Drive)</td></tr><tr><td style="text-align:center;">4 on (D1, D2, D3, D4)</td><td style="text-align:center;">Robotic Hand Control Mode (Left Hand)</td></tr><tr><td style="text-align:center;">5 on (D1, D2, D3, D4, D5)</td><td style="text-align:center;">Robotic Arm Control Mode (Bus Servo Drive)</td></tr></tbody></table><h2 id="_1-5-control-mode-instruction" tabindex="-1">1.5 Control Mode Instruction <a class="header-anchor" href="#_1-5-control-mode-instruction" aria-label="Permalink to &quot;1.5 Control Mode Instruction&quot;">​</a></h2><p>The wireless glove has four control modes, which are used for controlling products in the biorobot series, robotic hand series, tank robot series, and robotic arm series with a built-in Bluetooth module. The specific control methods for each type of product are shown in the table below:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Product Type</th><th style="text-align:center;">Examples</th></tr></thead><tbody><tr><td style="text-align:center;">Biorobot Series</td><td style="text-align:center;"><span class="mark">Narrow-footed robot, Cross-footed robot, S</span>piderbot</td></tr><tr><td style="text-align:center;"><span class="mark">Tank Robot Se</span>ries</td><td style="text-align:center;">Tankbot</td></tr><tr><td style="text-align:center;">Robotic Hand Series</td><td style="text-align:center;">uHand, uHand UNO</td></tr><tr><td style="text-align:center;">Robotic Arm Series</td><td style="text-align:center;">LeArm, xArm 1S, MiniArm</td></tr></tbody></table><h3 id="_1-5-1-biorobot" tabindex="-1">1.5.1 Biorobot <a class="header-anchor" href="#_1-5-1-biorobot" aria-label="Permalink to &quot;1.5.1 Biorobot&quot;">​</a></h3><p>The control of biorobot is mainly achieved through gesture control to make the robot perform a set of action <code>groups:</code></p><table tabindex="0"><thead><tr><th style="text-align:center;">Gesture Description</th><th style="text-align:center;">Gesture Image</th><th style="text-align:center;">Biorobot Feedback Action(from the robot’s view)</th></tr></thead><tbody><tr><td style="text-align:center;">Extend your middle finger, crook your ring finger, and tilt the palm to the right.</td><td style="text-align:center;"><img loading="lazy" height="314" width="236" src="'+u+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Turn right</td></tr><tr><td style="text-align:center;">Extend your middle finger, crook your ring finger, and tilt the palm to the left.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+w+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Turn left</td></tr><tr><td style="text-align:center;">Make a fist with the palm facing down.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+x+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Stop</td></tr><tr><td style="text-align:center;">Stretch your hand (straighten your middle finger) with the palm facing down.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+_+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Move forward</td></tr><tr><td style="text-align:center;">Crook your middle finger, and straighten your little finger with the palm facing up (Spider-Man gesture).</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+f+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Move backward</td></tr><tr><td style="text-align:center;">Stretch your hand with the palm facing up.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+b+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Stop</td></tr></tbody></table><h3 id="_1-5-2-tank-robot" tabindex="-1">1.5.2 Tank Robot <a class="header-anchor" href="#_1-5-2-tank-robot" aria-label="Permalink to &quot;1.5.2 Tank Robot&quot;">​</a></h3><p>You can control the tank robot by making specific gestures. The following table shows the available gestures and their corresponding feedback actions from the tank:</p><table><thead><tr><th style="text-align:center;">Initial Gesture</th><th style="text-align:center;">Gesture Description (from your perspective)</th><th style="text-align:center;">Gesture Image</th><th style="text-align:center;">Feedback Action from the Tank Robot (from the tank robot&#39;s perspective)</th></tr></thead><tbody><tr><td rowspan="4">Straighten your index and middle fingers, with the palm facing down (other fingers crooked in).</td><td style="text-align:center;">Raise your wrist, that is, your straightened fingers point forward and upward.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+v+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Move forward</td></tr><tr><td style="text-align:center;">Bend your wrist downward, that is, your straightened fingers point forward and downward.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+k+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Move backward</td></tr><tr><td style="text-align:center;">Bend your wrist clockwise, that is, the palm faces to the left.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+j+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Rotate clockwise in place.</td></tr><tr><td style="text-align:center;">Bend your wrist counterclockwise, that is, the palm faces to the right.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+D+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Rotate counterclockwise in place.</td></tr><tr><td colspan="3" style="text-align:center;">Other Gestures</td><td style="text-align:center;">Stop</td></tr></tbody></table><h3 id="_1-5-3-robotic-hand" tabindex="-1">1.5.3 Robotic Hand <a class="header-anchor" href="#_1-5-3-robotic-hand" aria-label="Permalink to &quot;1.5.3 Robotic Hand&quot;">​</a></h3><p>By bending or straightening your fingers, you can control the bending or straightening of the robotic hands’ corresponding fingers:</p>',43),t("table",{border:"1",cellpadding:"8",cellspacing:"0",style:{"border-collapse":"collapse","text-align":"center"}},[t("thead",null,[t("tr",null,[t("th",{style:{"text-align":"center"}},"Potentiometer Position"),t("th",{style:{"text-align":"center"}},"Gesture Image"),t("th",{style:{"text-align":"center"}},"Servo Controlled")])]),t("tbody",null,[t("tr",null,[t("td",{colspan:"2"},"Thumb"),t("td",null,"Servo 1")]),t("tr",null,[t("td",{colspan:"2"},"Index Finger"),t("td",null,"Servo 2")]),t("tr",null,[t("td",{colspan:"2"},"Middle Finger"),t("td",null,"Servo 3")]),t("tr",null,[t("td",{colspan:"2"},"Ring Finger"),t("td",null,"Servo 4")]),t("tr",null,[t("td",{colspan:"2"},"Little Finger"),t("td",null,"Servo 5")]),t("tr",null,[t("td",null,"Stretch your hand with the palm facing down, and your wrist rotates clockwise."),t("td",null,[t("img",{loading:"lazy",height:"308",width:"231",src:G,style:{width:"200px"},class:"inline-icon"})]),t("td",null,"The Pan-tilt rotates counterclockwise (from the perspective of the robotic hand).")]),t("tr",null,[t("td",null,"Stretch your hand with the palm facing down, and the wrist rotates counterclockwise."),t("td",null,[t("img",{loading:"lazy",height:"308",width:"231",src:W,style:{width:"200px"},class:"inline-icon"})]),t("td",null,"The Pan-tilt rotates clockwise (from the perspective of the robotic hand).")])])],-1),s('<h3 id="_1-5-4-robotic-arm" tabindex="-1">1.5.4 Robotic Arm <a class="header-anchor" href="#_1-5-4-robotic-arm" aria-label="Permalink to &quot;1.5.4 Robotic Arm&quot;">​</a></h3><p>You can control the robotic arm servos by making specific gestures. The following table shows the available gestures and the corresponding servo numbers they control:</p><table><colgroup><col style="width:16%;"><col style="width:42%;"><col style="width:24%;"><col style="width:16%;"></colgroup><tbody><tr><td style="text-align:center;">Initial Gesture</td><td style="text-align:center;">Gesture Description</td><td style="text-align:center;">Gesture Image</td><td style="text-align:center;">Servo Controlled</td></tr><tr><td rowspan="5" style="text-align:center;">The palm faces down.</td><td style="text-align:center;">Extend your index finger and tilt to the left or right.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+S+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Servo 1</td></tr><tr><td style="text-align:center;">Extend your index and middle fingers, and tilt to the left or right.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+T+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Servo 2</td></tr><tr><td style="text-align:center;">Extend your middle, ring, and little fingers, and tilt to the left or right.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+z+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Servo 3</td></tr><tr><td style="text-align:center;"><p>手掌向下，伸出四指，左倾或右倾</p><p>Extend your four fingers, and tilt to the left or right.</p></td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+P+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Servo 4</td></tr><tr><td style="text-align:center;">Stretch your hand with the palm facing down, and tilt to the left or right.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+B+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Servo 5</td></tr><tr><td style="text-align:center;">The palm faces down.</td><td style="text-align:center;">Make a fist with the palm facing down, and tilt to the left or right.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+A+'" style="width:200px;" class="inline-icon"></td><td style="text-align:center;">Servo 6</td></tr></tbody></table>',3)])])}const N=o(C,[["render",I]]);export{F as __pageData,N as default};
